//go:build riscv64

package floats

// RVV 1.0 Abs, Neg and Square kernels (round.go, gated on hasRVV,
// kernels_riscv64.go), generated by go-asmgen (round_riscv64_gen.go) into
// round_riscv64.s. They are vector-length agnostic: no scalar tail. RVV 1.0 has no
// vector round-to-integral instruction, so Floor, Ceil, Trunc and RoundEven run
// the portable loop on riscv64 (see round_riscv64_gen.go).
//
//go:noescape
func absRVV(dst, src *float64, n int)

//go:noescape
func negRVV(dst, src *float64, n int)

//go:noescape
func squareRVV(dst, src *float64, n int)

func vabs(dst, src []float64) {
	if len(src) == 0 || !hasRVV {
		absRef(dst, src)
		return
	}
	absRVV(&dst[0], &src[0], len(src))
}

func vneg(dst, src []float64) {
	if len(src) == 0 || !hasRVV {
		negRef(dst, src)
		return
	}
	negRVV(&dst[0], &src[0], len(src))
}

func vsquare(dst, src []float64) {
	if len(src) == 0 || !hasRVV {
		squareRef(dst, src)
		return
	}
	squareRVV(&dst[0], &src[0], len(src))
}

func vfloor(dst, src []float64) { floorRef(dst, src) }
func vceil(dst, src []float64)  { ceilRef(dst, src) }
func vtrunc(dst, src []float64) { truncRef(dst, src) }
func vrint(dst, src []float64)  { rintRef(dst, src) }
